package com.bank.usage.repository;

import com.bank.usage.model.Transaction;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.math.BigDecimal;
import java.util.List;

public interface ReportRepository extends JpaRepository<Transaction, String> {

    // WHERE uses ix_amount + ix_acct_date (filter on account_id and amount)
    List<Transaction> findByAccountIdAndAmountGreaterThan(String accountId, BigDecimal amount);

    // ORDER BY uses ix_acct_date — no extra sort step
    List<Transaction> findByAccountIdOrderByCreatedAtAsc(String accountId);

    // GROUP BY uses ix_branch — rows for each branch sit adjacently
    @Query("SELECT t.branchCode, SUM(t.amount) FROM Transaction t GROUP BY t.branchCode")
    List<Object[]> totalPerBranch();
}
