package com.bank.usage.service;

import com.bank.usage.model.Transaction;
import com.bank.usage.repository.ReportRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.List;

@Service
public class ReportingService {
    private static final Logger log = LoggerFactory.getLogger(ReportingService.class);
    private final ReportRepository repo;

    public ReportingService(ReportRepository repo) { this.repo = repo; }

    public List<Transaction> largeTransactions(String accountId, BigDecimal threshold) {
        log.info("WHERE: account {} amount > {} (uses ix_amount)", accountId, threshold);
        return repo.findByAccountIdAndAmountGreaterThan(accountId, threshold);
    }

    public List<Transaction> orderedByDate(String accountId) {
        log.info("ORDER BY: account {} by created_at (uses ix_acct_date, no sort)", accountId);
        return repo.findByAccountIdOrderByCreatedAtAsc(accountId);
    }

    public List<Object[]> branchTotals() {
        log.info("GROUP BY: total per branch (uses ix_branch)");
        return repo.totalPerBranch();
    }
}
